package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.*;import net.minecraft.core.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.phys.*;import net.minecraftforge.client.event.*;import net.minecraftforge.eventbus.api.SubscribeEvent;import com.mojang.math.Axis;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.minecraftforge.api.distmarker.Dist.CLIENT)
public final class AdcClient{
 public static net.minecraft.client.renderer.culling.Frustum frustum;public static void open(AdcBlockEntity b){Minecraft.getInstance().setScreen(new AdcScreen(b));}
 private static BlockPos site;private static Direction facing;private static int kind;private static String reason="";private static long checked;private static Object world;
 private static boolean update(){var m=Minecraft.getInstance();if(m.level==null||m.player==null||m.screen!=null||!(m.player.getMainHandItem().getItem()instanceof AdcItem item)||!(m.hitResult instanceof BlockHitResult hit)||hit.getType()!=HitResult.Type.BLOCK||hit.getDirection()!=Direction.UP){site=null;return false;}var c=new BlockPlaceContext(m.player,net.minecraft.world.InteractionHand.MAIN_HAND,m.player.getMainHandItem(),hit);var face=DefenseItem.face(m.player,m.player.getMainHandItem());var root=AdcItem.anchor(c.getClickedPos(),face);if(world!=m.level||!root.equals(site)||facing!=face||m.level.getGameTime()-checked>=5){world=m.level;site=root;facing=face;checked=m.level.getGameTime();reason=AdcItem.check(m.level,root,face,m.player,m.player.getMainHandItem());}return true;}
 @SubscribeEvent public static void preview(RenderLevelStageEvent e){frustum=e.getFrustum();if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||!update())return;var m=Minecraft.getInstance();var camera=e.getCamera().getPosition();var p=e.getPoseStack();var buffers=m.renderBuffers().bufferSource();p.pushPose();p.translate(site.getX()+.5-camera.x,site.getY()-camera.y,site.getZ()+.5-camera.z);p.mulPose(Axis.YP.rotationDegrees(180-facing.toYRot()));AdcModel.get().draw(p,buffers,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,0,25,0,0,5,true,reason.isEmpty());p.popPose();buffers.endBatch();}
 @SubscribeEvent public static void hud(RenderGuiEvent.Post e){if(!update())return;var m=Minecraft.getInstance();var text=net.minecraft.network.chat.Component.translatable("defense.preview",net.minecraft.network.chat.Component.translatable("defense.status."+(reason.isEmpty()?"CLEAR":reason)));e.getGuiGraphics().drawCenteredString(m.font,text,m.getWindow().getGuiScaledWidth()/2,m.getWindow().getGuiScaledHeight()-62,reason.isEmpty()?0xff85e3a4:0xffff8c85);}
}
